    uint32_t kh = wDims.size() >= 4 ? static_cast<uint32_t>(wDims[3]) : 1;
    uint32_t kw = wDims.size() >= 5 ? static_cast<uint32_t>(wDims[4]) : 1;

    // Default attributes in case they are not provided as constants
    uint32_t sd = 1, sh = 1, sw = 1;
    uint32_t pd = 0, ph = 0, pw = 0;
    uint32_t opd = 0, oph = 0, opw = 0;
    uint32_t groups = 1;

    // Try to get attributes from the input shapes (treat as small tensors [3] or [1])
    if (context->GetInputsSize() >= 6) {
        const gert::Shape* strideShape = context->GetInputShape(2);
        const gert::Shape* padShape = context->GetInputShape(3);
        const gert::Shape* outPadShape = context->GetInputShape(4);
        const gert::Shape* groupsShape = context->GetInputShape(5);
        if (strideShape && strideShape->GetOriginShape().GetShapeSize() >= 3) {
