static inline at::Tensor to_int_tensor_1d(const std::vector<int64_t>& vals, c10::Device dev) {
    at::Tensor t = at::empty({(long)vals.size()}, at::TensorOptions().dtype(at::kInt).device(dev));
    auto acc = t.accessor<int32_t,1>();
    for (int64_t i = 0; i < (int64_t)vals.size(); ++i) acc[i] = static_cast<int32_t>(vals[i]);
    return t;
}

at::Tensor conv_transposed_3d_asymmetric_input_asymmetric_kernel_strided_padded_grouped_custom_impl_npu(
    const at::Tensor& x,
    const at::Tensor& weight,
    c10::optional<at::IntArrayRef> stride_opt,
    c10::optional<at::IntArrayRef> padding_opt,
    c10::optional<at::IntArrayRef> output_padding_opt,
    int64_t groups)
{
    auto stride = stride_opt.has_value() ? stride_opt.value() : at::IntArrayRef({1,1,1});
    auto padding = padding_opt.has_value() ? padding_opt.value() : at::IntArrayRef({0,0,0});
    auto out_pad = output_padding_opt.has_value() ? output_padding_opt.value() : at::IntArrayRef({0,0,0});

    // Input: x [N, Cin, Di, Hi, Wi], weight [Cin, Cout/group, Kd, Kh, Kw]
    auto N = x.size(0); auto Cin = x.size(1); auto Di = x.size(2); auto Hi = x.size(3); auto Wi = x.size(4);
    auto Kd = weight.size(2); auto Kh = weight.size(3); auto Kw = weight.size(4);
    auto Sd = stride.size() >= 1 ? stride[0] : 1;
    auto Sh = stride.size() >= 2 ? stride[1] : 1;
    auto Sw = stride.size() >= 3 ? stride[2] : 1;
    auto Pd = padding.size() >= 1 ? padding[0] : 0;
    auto Ph = padding.size() >= 2 ? padding[1] : 0;
    auto Pw = padding.size() >= 3 ? padding[2] : 0;
    auto OPd = out_pad.size() >= 1 ? out_pad[0] : 0;
    auto OPh = out_pad.size() >= 2 ? out_pad[1] : 0;
    auto OPw = out_pad.size() >= 3 ? out_pad[2] : 0;

    int64_t CoutPerGroup = weight.size(1);
    int64_t Cout = CoutPerGroup * groups;

    int64_t Do = (Di > 0 ? (Di - 1) * Sd : 0) - 2 * Pd + Kd + OPd;
    int64_t Ho = (Hi > 0 ? (Hi - 1) * Sh : 0) - 2 * Ph + Kh + OPh;
    int64_t Wo = (Wi > 0 ? (Wi - 1) * Sw : 0) - 2 * Pw + Kw + OPw;

    at::Tensor y = at::empty({N, Cout, Do, Ho, Wo}, x.options());
    // Pack attributes as small int tensors
    std::vector<int64_t> stride_vec = {Sd, Sh, Sw};
    std::vector<int64_t> pad_vec = {Pd, Ph, Pw};
    std::vector<int64_t> outpad_vec = {OPd, OPh, OPw};
    at::Tensor stride_t = to_int_tensor_1d(stride_vec, x.device());
    at::Tensor padding_t = to_int_tensor_1d(pad_vec, x.device());
    at::Tensor outpad_t = to_int_tensor_1d(outpad_vec, x.device());
    at::Tensor groups_t = to_int_tensor_1d({groups}, x.device());

    EXEC_NPU_CMD(aclnnConvTransposed3dAsymmetricInputAsymmetricKernelStridedPaddedGroupedCustom,
                 x, weight, stride_t, padding_t, outpad_t, groups_t, y);
    return y;
}

