class ModelNew(torch.nn.Module):
    """
    使用自定义 AscendC Kernel 实现 3D 反卷积（转置卷积），支持不对称 kernel、stride、padding、output_padding 和分组。
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        # 复用 PyTorch 的参数管理与权重初始化
        self.conv_transpose3d = torch.nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # 调用自定义算子实现核心计算（当前不处理 bias，若需要可在外部添加）
        y = custom_ops_lib.conv_transposed_3d_asymmetric_input_asymmetric_kernel_strided_padded_grouped_custom(
            x, self.conv_transpose3d.weight, self.conv_transpose3d.stride,
            self.conv_transpose3d.padding, self.conv_transpose3d.output_padding,
            self.conv_transpose3d.groups
        )
        if self.conv_transpose3d.bias is not None:
            # 按 PyTorch 语义广播加上 bias
            y = y + self.conv_transpose3d.bias.view(1, -1, 1, 1, 1)
        return y
